actions.script:
String comp = componentName?.trim()?.replaceAll("[^a-zA-Z0-9_-]", "") if (!comp) { context.exists = false context.gitExists = false context.blueprintExists = false context.initialized = false return }
File baseDir = new File("runtime/component/" + comp) boolean exists = baseDir.exists() boolean gitExists = new File(baseDir, ".git").exists() boolean blueprintExists = new File(baseDir, "mcp/instructions/component.md").exists()
context.exists = exists context.gitExists = gitExists context.blueprintExists = blueprintExists
// A component is considered strictly "initialized" for AI if all 3 pieces are in place context.initialized = (exists && gitExists && blueprintExists)

String srcUri = sourceArtifactUri?.trim()
String targetComp = targetComponent?.trim()?.toLowerCase()?.replaceAll("[^a-z0-9-]", "")

if (!srcUri || !targetComp) {
    context.success = false
    context.message = "Missing sourceArtifactUri or targetComponent."
    ec.message.addError(context.message)
    return
}

// 1. Resolve source file content
org.moqui.resource.ResourceReference srcRr = ec.resource.getLocationReference(srcUri)
if (srcRr == null || !srcRr.getExists()) {
    context.success = false
    context.message = "Source artifact not found at: ${srcUri}"
    ec.message.addError(context.message)
    return
}
String content = srcRr.getText() ?: ""

// 2. Compute mirrored relative path
// e.g. "component://agi-ide/mcp/instructions/artifacts/screen/build.md" -> "mcp/instructions/artifacts/screen/build.md"
String cleanPath = srcUri
if (cleanPath.startsWith("component://")) {
    cleanPath = cleanPath.substring("component://".length())
    int slashIdx = cleanPath.indexOf('/')
    if (slashIdx != -1) cleanPath = cleanPath.substring(slashIdx + 1)
}

// 3. Verify target component exists on disk
File targetCompDir = new File("runtime/component/" + targetComp)
if (!targetCompDir.exists()) {
    context.success = false
    context.message = "Target component '${targetComp}' does not exist on disk."
    ec.message.addError(context.message)
    return
}

// 4. Check if target override already exists
File targetFile = new File(targetCompDir, cleanPath)
String destArtifactUri = "component://${targetComp}/${cleanPath}"
if (targetFile.exists()) {
    context.success = true
    context.targetArtifactUri = destArtifactUri
    context.message = "Override file already exists at: ${destArtifactUri}"
    ec.logger.info("ℹ️ [create#ComponentOverride] Target file already exists: ${destArtifactUri}")
    return
}

// 5. Write mirrored file to disk
targetFile.parentFile.mkdirs()
targetFile.text = content

// 6. Record Git baseline in target component repo if .git exists
File gitDir = new File(targetCompDir, ".git")
if (gitDir.exists()) {
    try {
        ProcessBuilder pbAdd = new ProcessBuilder(["git", "add", cleanPath])
        pbAdd.directory(targetCompDir)
        pbAdd.start().waitFor()

        ProcessBuilder pbCommit = new ProcessBuilder(["git", "commit", "-m", "Override ${cleanPath} from platform"])
        pbCommit.directory(targetCompDir)
        pbCommit.start().waitFor()
        ec.logger.info("🔧 [create#ComponentOverride] Git committed override ${cleanPath} in ${targetComp}")
    } catch (Exception gitEx) {
        ec.logger.warn("⚠️ [create#ComponentOverride] Git commit skipped: ${gitEx.message}")
    }
}

context.success = true
context.targetArtifactUri = destArtifactUri
context.message = "Successfully created override at ${destArtifactUri}"
ec.logger.info("✅ [create#ComponentOverride] Created override: ${destArtifactUri}")

// Sanitization String compName = componentName.trim().toLowerCase().replaceAll("[^a-z0-9-]", "") if (!compName) { ec.message.addError("Invalid component name specified.") return }
// 1. Locate Runtime Component Directory String runtimeCompPath = "runtime/component/" + compName File baseDir = new File(runtimeCompPath) if (baseDir.exists()) { ec.message.addError("Component directory already exists at: " + runtimeCompPath) return }
// 2. Build Directory Skeleton (screen directory directly under component) // Note: Do NOT create an empty entity/ folder upfront, as EntityFacade scans empty entity // folders and triggers NullPointerException in loadEntityDefinition when entityRoot is null. File serviceDir = new File(baseDir, "service/" + compName.replace('-', '/')) File screenDir = new File(baseDir, "screen") File dataDir = new File(baseDir, "data") File mcpDir = new File(baseDir, "mcp/instructions")
serviceDir.mkdirs() screenDir.mkdirs() dataDir.mkdirs() mcpDir.mkdirs()
// 2b. Seed component.md blueprint String blueprintText = """# Architecture Directives: ${compName.toUpperCase()} <!-- Canonical domain specification for ${compName}. High-level invariants and functional policies. -->
## 1. Domain Scope & Core Capabilities - Primary operational workflows for ${compName}.
## 2. Mantle UDM Data Model Invariants - Extend existing Mantle entities (e.g. mantle.facility.Facility, mantle.party.Party). - No redundant custom tables for core party or facility domains.
## 3. Compliance, Privacy & HIPAA Invariants - Encrypt PHI fields; enable audit logs on clinical records.
## 4. UI & Navigation Invariants - Master-detail layouts; subscreen item routing. """ new File(mcpDir, "component.md").text = blueprintText
// 3. Generate component.xml based on Preset String componentXmlContent = "" if (preset == "mantle-domain") { componentXmlContent = """<?xml version="1.0" encoding="UTF-8"?> <component xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/component-3.0.xsd" name="${compName}"> <!-- Depends on Mantle Universal Data Model (UDM/USL) --> <depends on="mantle-usl"/> </component> """ } else if (preset == "web-app") { componentXmlContent = """<?xml version="1.0" encoding="UTF-8"?> <component xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/component-3.0.xsd" name="${compName}"> <depends on="webroot"/> </component> """ } else { componentXmlContent = """<?xml version="1.0" encoding="UTF-8"?> <component xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/component-3.0.xsd" name="${compName}"> </component> """ }
new File(baseDir, "component.xml").text = componentXmlContent
// 3b. Generate MoquiConf.xml to mount root screen into webroot String menuTitle = description ?: compName.capitalize() String moquiConfContent = """<?xml version="1.0" encoding="UTF-8"?> <moqui-conf xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/moqui-conf-3.xsd"> <screen-facade> <screen location="component://webroot/screen/webroot.xml"> <subscreens-item name="${compName}" menu-title="${menuTitle}" location="component://${compName}/screen/${compName}.xml"/> </screen> </screen-facade> </moqui-conf> """ new File(baseDir, "MoquiConf.xml").text = moquiConfContent
// 4. Generate Root Screen XML Shell directly under screen/ (${compName}.xml) String rootScreenPath = "component://${compName}/screen/${compName}.xml" String rootScreenXml = """<?xml version="1.0" encoding="UTF-8"?> <screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/xml-screen-3.xsd" require-authentication="true" editor="AgiBlueprintEditor">
<widgets> <container id="${compName}-root"> <label text="${description ?: 'Root screen for ' + compName}" type="h4"/> </container> </widgets> </screen> """ File rootScreenFile = new File(screenDir, compName + ".xml") rootScreenFile.text = rootScreenXml
// 5. Idempotent Registration/Update of Primary Artifact in AgiArtifact def enumCheck = ec.entity.find("moqui.basic.Enumeration").condition("enumId", "AatXmlScreen").one() String typeEnumId = enumCheck ? "AatXmlScreen" : null
def artifactVal = ec.entity.find("org.moqui.ai.AgiArtifact") .condition("artifactPath", rootScreenPath) .one()
if (!artifactVal) { artifactVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact") artifactVal.set("artifactPath", rootScreenPath) artifactVal.set("artifactTypeEnumId", typeEnumId) artifactVal.set("artifactStatusEnumId", "AasDraft") artifactVal.set("totalIntentCount", 1) artifactVal.set("completedIntentCount", 0) artifactVal.set("completionPercentage", 0.0) artifactVal.setSequencedIdPrimary() artifactVal.create() } else { artifactVal.set("artifactTypeEnumId", typeEnumId) artifactVal.set("artifactStatusEnumId", "AasDraft") artifactVal.set("totalIntentCount", 1) artifactVal.set("completedIntentCount", 0) artifactVal.set("completionPercentage", 0.0) artifactVal.update() }
// Auto-Seed Description as Root Intent if (description && description.trim()) { ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([ workEffortName: "Root Intent: " + compName, description: description, agiArtifactId: artifactVal.agiArtifactId, sourceReferenceId: rootScreenPath, workEffortTypeEnumId: "WetIntent" ]).call() }
// 6. Initialize Git Version Control try { def execGit = { List<String> args -> ProcessBuilder pb = new ProcessBuilder(args) pb.directory(baseDir) Process p = pb.start() p.waitFor() } execGit(["git", "init"]) execGit(["git", "branch", "-M", "main"]) execGit(["git", "add", "."]) execGit(["git", "commit", "-m", "Initial AI component scaffold"]) ec.logger.info("🔧 [AGI SCAFFOLD] Git repository initialized for ${compName}") } catch (Exception gitEx) { ec.logger.warn("⚠️ [AGI SCAFFOLD] Git initialization failed for ${compName}: ${gitEx.message}") }
context.componentPath = runtimeCompPath context.rootArtifactPath = rootScreenPath
ec.logger.info("🚀 [AGI SCAFFOLD] Component '${compName}' successfully initialized on disk at ${runtimeCompPath}")

String comp = componentName?.trim()?.replaceAll("[^a-zA-Z0-9_-]", "")
List systemProtected = ['agi-ide', 'agi-ai', 'moqui-usl', 'mantle-usl', 'webroot', 'tools']
if (!comp || systemProtected.contains(comp)) {
    context.success = false
    context.message = "Cannot delete protected system component: '${comp}'."
    return
}

ec.logger.warn("⚠️ [drop#Component] Initiating complete purge for component: ${comp}")

// 1. Resolve Discussion IDs
def discs = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
    .condition("targetComponent", comp)
    .list()
List discIds = discs*.discussionId ?: []

// 2. Resolve all Payloads tied either to component or discussion IDs
Set<String> payloadIdSet = new HashSet<>()
def compPayloads = ec.entity.find("org.moqui.ai.payload.AgiPayload")
    .condition("targetComponent", comp)
    .list()
compPayloads.each { payloadIdSet.add(it.agiPayloadId as String) }

if (discIds) {
    def discPayloads = ec.entity.find("org.moqui.ai.payload.AgiPayload")
        .condition("discussionId", "in", discIds)
        .list()
    discPayloads.each { payloadIdSet.add(it.agiPayloadId as String) }
}

List payloadIds = payloadIdSet.toList()
def allTargetPayloads = payloadIds ? ec.entity.find("org.moqui.ai.payload.AgiPayload")
    .condition("agiPayloadId", "in", payloadIds)
    .list() : []

// -------------------------------------------------------------
// 3. DISSOLVE ALL SELF-REFERENTIAL AND CROSS-ENTITY CONSTRAINTS
// -------------------------------------------------------------
allTargetPayloads.each { p ->
    if (p.parentPayloadId) {
        p.parentPayloadId = null
        p.update()
    }
}

if (discIds) {
    def steps = ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
        .condition("discussionId", "in", discIds)
        .list()
    steps.each { s ->
        s.parentStepId = null
        s.ingressPayloadId = null
        s.egressPayloadId = null
        s.assistantMessageId = null
        s.userMessageId = null
        s.update()
    }
}

if (discIds) {
    def msgs = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("discussionId", "in", discIds)
        .list()
    msgs.each { m ->
        m.parentMessageId = null
        m.stagedPayloadId = null
        m.update()
    }
}

// -------------------------------------------------------------
// 4. PURGE LEAF AND FACET TABLES
// -------------------------------------------------------------
if (payloadIds) {
    ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet")
        .condition("agiPayloadId", "in", payloadIds)
        .deleteAll()
}

if (discIds) {
    def allMsgs = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("discussionId", "in", discIds)
        .list()
    List msgIds = allMsgs*.messageId ?: []
    if (msgIds) {
        ec.entity.find("org.moqui.ai.discussion.AgiMessageContent")
            .condition("messageId", "in", msgIds)
            .deleteAll()
        ec.entity.find("org.moqui.ai.discussion.AgiMessageFacet")
            .condition("messageId", "in", msgIds)
            .deleteAll()
    }

    ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet")
        .condition("discussionId", "in", discIds)
        .deleteAll()
    ec.entity.find("org.moqui.ai.discussion.AgiDiscussionRelationship")
        .condition("parentDiscussionId", "in", discIds)
        .deleteAll()
    ec.entity.find("org.moqui.ai.discussion.AgiDiscussionRelationship")
        .condition("childDiscussionId", "in", discIds)
        .deleteAll()

    // Purge native moqui.llm tracking rows tied to these discussions
    try {
        ec.entity.find("moqui.llm.LlmCallLog").condition("conversationId", "in", discIds).deleteAll()
        ec.entity.find("moqui.llm.LlmMessage").condition("conversationId", "in", discIds).deleteAll()
        ec.entity.find("moqui.llm.LlmConversation").condition("conversationId", "in", discIds).deleteAll()
    } catch (Exception ignore) {}
}

// -------------------------------------------------------------
// 5. PURGE CORE RELATIONAL ENTITIES (Steps -> Payloads -> Messages -> Discussions)
// -------------------------------------------------------------
if (discIds) {
    ec.entity.find("org.moqui.ai.pipeline.AgiPipelineStep")
        .condition("discussionId", "in", discIds)
        .deleteAll()
}

allTargetPayloads.each { p ->
    p.delete()
}

if (discIds) {
    def remainingMsgs = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("discussionId", "in", discIds)
        .list()
    remainingMsgs.each { rm -> rm.delete() }

    def remainingDiscs = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
        .condition("discussionId", "in", discIds)
        .list()
    remainingDiscs.each { rd -> rd.delete() }
}

// -------------------------------------------------------------
// 6. PURGE ARTIFACT JOIN TABLES, WORK EFFORTS, AND ARTIFACTS
// -------------------------------------------------------------
try {
    String compPattern = ("%" + comp + "%").toString()

    def allArtifacts = ec.entity.find("org.moqui.ai.AgiArtifact")
        .condition("artifactPath", org.moqui.entity.EntityCondition.ComparisonOperator.LIKE, compPattern)
        .list()

    List artIds = allArtifacts*.agiArtifactId?.findAll { it != null } ?: []

    if (artIds) {
        try {
            ec.entity.find("org.moqui.ai.AgiArtifactWorkEffort")
                .condition("agiArtifactId", "in", artIds)
                .deleteAll()
        } catch (Exception ignore) {}

        def linkedWorkEfforts = ec.entity.find("mantle.work.effort.WorkEffort")
            .condition("agiArtifactId", "in", artIds)
            .list()
        linkedWorkEfforts.each { we ->
            we.agiArtifactId = null
            we.update()
        }

        allArtifacts.each { art ->
            if (art.artifactPath) {
                ec.entity.find("mantle.work.effort.WorkEffort")
                    .condition("sourceReferenceId", art.artifactPath.toString())
                    .deleteAll()
            }
        }

        linkedWorkEfforts.each { we ->
            try { we.delete() } catch (Exception ignore) {}
        }

        ec.entity.find("org.moqui.ai.AgiArtifact")
            .condition("agiArtifactId", "in", artIds)
            .deleteAll()
    }

    ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("sourceReferenceId", org.moqui.entity.EntityCondition.ComparisonOperator.LIKE, compPattern)
        .deleteAll()

} catch (Exception ex) {
    ec.logger.error("⚠️ [drop#Component] Error purging AgiArtifact hierarchy: ${ex.message}", ex)
}

// -------------------------------------------------------------
// 7. PURGE WORKSPACE BUFFERS
// -------------------------------------------------------------
try {
    String bufPattern = ("%" + comp + "%").toString()
    ec.entity.find("org.moqui.ai.WorkspaceBuffer")
        .condition("artifactUri", org.moqui.entity.EntityCondition.ComparisonOperator.LIKE, bufPattern)
        .deleteAll()
} catch (Exception ex) {
    ec.logger.warn("⚠️ [drop#Component] Error purging WorkspaceBuffer: ${ex.message}")
}

// -------------------------------------------------------------
// 8. PURGE PHYSICAL FILESYSTEM DIRECTORY
// -------------------------------------------------------------
File compDir = new File("runtime/component/${comp}")
boolean fileSuccess = true
if (compDir.exists()) {
    fileSuccess = compDir.deleteDir()
    ec.logger.info("🗑️ [drop#Component] Directory purge for ${compDir.getPath()}: ${fileSuccess}")
}

// -------------------------------------------------------------
// 9. CLEAR CACHES (Resource, Screen, and Entity)
// -------------------------------------------------------------
try {
    ec.resource.clearAllCaches()
    ec.screen.clearScreenCache(true)
    // Clear Entity Node and Definition caches so EntityFacade unloads the component
    if (ec.entity != null) {
        try { ec.entity.clearNodeCache() } catch (Exception ignore) {}
        try { ec.entity.clearCacheFinds() } catch (Exception ignore) {}
    }
} catch (Exception ignore) {}

context.success = fileSuccess
context.message = fileSuccess ? "Component '${comp}' was completely removed from database and disk."
                              : "Database purged, but physical directory could not be fully deleted."
ec.logger.info("✅ [drop#Component] Purge complete for ${comp}: ${context.message}")

                import groovy.json.JsonSlurper
                import groovy.json.JsonOutput

                String text = (narrative ?: "").toLowerCase().trim()
                if (!text || text.length() < 10) {
                    context.suggestedArchetype = "custom"
                    context.confidence = 0.5
                    return
                }

                // 1. Instant Server Heuristic Fallback (Fast, sub-millisecond)
                def scores = [
                    'huddle-ops': 0,
                    'clinical-registry': 0,
                    'facility-asset': 0,
                    'service-case': 0
                ]

                def huddleKw = ['huddle', 'shift', 'standup', 'census', 'acuity', 'turnover', 'nurse', 'vitals']
                def clinicKw = ['patient', 'care plan', 'clinical', 'diagnosis', 'treatment', 'medication', 'mar', 'chart']
                def assetKw  = ['facility', 'room', 'bed', 'equipment', 'maintenance', 'repair', 'asset', 'work order']
                def caseKw   = ['intake', 'case', 'ticket', 'request', 'complaint', 'incident', 'billing', 'workflow']

                huddleKw.each { if (text.contains(it)) scores['huddle-ops'] += 2 }
                clinicKw.each { if (text.contains(it)) scores['clinical-registry'] += 2 }
                assetKw.each  { if (text.contains(it)) scores['facility-asset'] += 2 }
                caseKw.each   { if (text.contains(it)) scores['service-case'] += 2 }

                def maxEntry = scores.max { it.value }
                String heuristicResult = (maxEntry && maxEntry.value > 0) ? maxEntry.key : "custom"

                // 2. Micro-Inference Fast-Path (Optional AI validation if AI facade is present)
                try {
                    String systemPrompt = """You are an application classifier. Given the narrative description, classify into EXACTLY ONE archetype:
- huddle-ops (shifts, standups, handoffs, time-critical operational checklists)
- clinical-registry (residents, patients, long-term logs, care plans, vitals)
- facility-asset (work orders, maintenance, equipment, facility rooms)
- service-case (intake tickets, case workflows, customer requests)
- custom (none of the above)

Return JSON ONLY: {"archetype": "id", "confidence": 0.95}"""

                    Map aiResult = ec.service.sync()
                        .name("org.moqui.ai.AgiAiGatewayServices.run#OpenAiProxy")
                        .parameters([
                            systemInstruction: systemPrompt,
                            userPrompt: narrative,
                            mode: "classify",
                            aiProfileName: "gemini"
                        ])
                        .call()

                    String reply = aiResult?.completionText ?: ""
                    def matcher = reply =~ /\{.*"archetype"\s*:\s*"([^"]+)".*\}/
                    if (matcher.find()) {
                        context.suggestedArchetype = matcher.group(1)
                        context.confidence = 0.95
                        return
                    }
                } catch (Exception ex) {
                    ec.logger.warn("⚠️ [classify#AppIntent] Fast AI classify fallback to server heuristic: ${ex.message}")
                }

                // Default to heuristic match if AI call times out or errors
                context.suggestedArchetype = heuristicResult
                context.confidence = (maxEntry && maxEntry.value > 0) ? 0.85 : 0.5
